export function Popover({title, trigger, children}: PopoverProps) {
  const id = useId();
  const titleId = `${id}-title`;
  const anchorRef = useRef<HTMLSpanElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const place = () => {
    if (anchorRef.current && panelRef.current) positionOverlay(anchorRef.current, panelRef.current);
  };
  const focusTrigger = () => anchorRef.current?.querySelector<HTMLElement>('[popovertarget]')?.focus();

  useEffect(() => {
    if (!open) return;
    window.addEventListener('resize', place);
    window.addEventListener('scroll', place, true);
    return () => {
      window.removeEventListener('resize', place);
      window.removeEventListener('scroll', place, true);
    };
  }, [open]);

  const handleToggle = () => {
    const panel = panelRef.current;
    const nextOpen = panel?.matches(':popover-open') ?? false;
    setOpen(nextOpen);
    if (nextOpen) {
      place();
      panel?.focus();
    } else if (panel?.contains(document.activeElement)) {
      focusTrigger();
    }
  };

  return <span ref={anchorRef} className="fds-popover-anchor">{cloneElement(trigger, {popoverTarget: id, 'aria-expanded': open, 'aria-haspopup': 'dialog'})}<div ref={panelRef} id={id} popover="auto" role="dialog" aria-labelledby={titleId} tabIndex={-1} className="fds-popover" onToggle={handleToggle} onKeyDown={(event) => {if (event.key === 'Escape') {event.preventDefault(); panelRef.current?.hidePopover(); focusTrigger();}}}><div className="fds-popover__header"><strong id={titleId}>{title}</strong><IconButton aria-label="Close" size="small" popoverTarget={id} popoverTargetAction="hide"><Icon name="close" /></IconButton></div><div className="fds-popover__content">{children}</div></div></span>;
}

import {cloneElement, useId, useRef, type HTMLAttributes, type ReactElement, type ReactNode} from 'react';
import {positionOverlay} from './positionOverlay';

type TooltipTriggerProps = {'aria-describedby'?: string};
export type TooltipProps = {content: ReactNode; children: ReactElement<TooltipTriggerProps>};

export function Tooltip({content, children}: TooltipProps) {
  const id = useId();
  const anchorRef = useRef<HTMLSpanElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const timerRef = useRef<number | undefined>(undefined);
  const describedBy = [children.props['aria-describedby'], id].filter(Boolean).join(' ');
  const hide = () => {
    window.clearTimeout(timerRef.current);
    if (tooltipRef.current?.matches(':popover-open')) tooltipRef.current.hidePopover();
  };
  const show = () => {
    const anchor = anchorRef.current;
    const tooltip = tooltipRef.current;
    if (!anchor || !tooltip || tooltip.matches(':popover-open')) return;
    tooltip.showPopover();
    positionOverlay(anchor, tooltip, 'center');
  };
  const delayShow = () => {
    window.clearTimeout(timerRef.current);
    timerRef.current = window.setTimeout(show, 400);
  };
  const handleBlur: HTMLAttributes<HTMLSpanElement>['onBlur'] = (event) => {
    if (!event.currentTarget.contains(event.relatedTarget)) hide();
  };

  return <span ref={anchorRef} className="fds-tooltip-anchor" onMouseEnter={delayShow} onMouseLeave={hide} onFocus={show} onBlur={handleBlur} onKeyDown={(event) => {if (event.key === 'Escape') hide();}}>{cloneElement(children, {'aria-describedby': describedBy})}<div ref={tooltipRef} id={id} role="tooltip" popover="manual" className="fds-tooltip">{content}</div></span>;
}

import {useState} from 'react';
